mapper.select:
SELECT a.OperatorID AS operateId, (SELECT OperatorName FROM dbtoms.tboperatorinfo WHERE a.OperatorID = OperatorID ORDER BY LastUpdateTime DESC LIMIT 1) AS operateName, SUM(a.CardNum) as cardNum, (SELECT LaneName FROM dbtoms.tblaneinfo WHERE a.LaneID = LaneID AND a.StationID = StationID limit 1) AS laneName FROM tbstatentry a
AND StationID = #{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
GROUP BY OperatorID ORDER BY OperatorID ASC

SELECT
OperatorID AS operatorId,
IFNULL(SUM(HandInCNum), 0) AS sjCardNum,
IFNULL(SUM(HandToll)/100, 0) AS sjCash,
IFNULL(SUM(AddedToll)/100, 0) AS addedToll
FROM ${tableName}


        AND StationID = #{stationId}


        AND StaDate >= #{intBeginTime}


        AND StaDate <= #{intEndTime}


GROUP BY OperatorID
ORDER BY OperatorID ASC

SELECT a.OperatorID AS operatorId, (SELECT OperatorName FROM dbtoms.tboperatorinfo WHERE a.OperatorID = OperatorID ORDER BY LastUpdateTime DESC LIMIT 1 ) AS operatorName, IFNULL(SUM(a.CarNum),0) totalCarNum, IFNULL(SUM(CASE WHEN a.CardType=26 THEN a.CarNum ELSE 0 END),0) yjCardNum, IFNULL(CAST(SUM(CASE WHEN a.PayType=0 THEN a.TotalToll ELSE 0 END) /100 as DECIMAL(20,2)),0) sjCash, IFNULL(CAST(SUM(CASE WHEN a.PayType=16 THEN a.TotalToll ELSE 0 END)/100 as DECIMAL(10,2)), 0) mPay, IFNULL(CAST(SUM(CASE WHEN a.PayType=2 THEN a.TotalToll ELSE 0 END) /100 as DECIMAL(10,2)), 0) as ePay FROM tbstatexit a
AND a.StationID = #{stationId}
AND a.StaDate >= #{intBeginTime}
AND a.StaDate <= #{intEndTime}
GROUP BY a.OperatorID ORDER BY a.OperatorID ASC

SELECT a.OperatorID AS operatorId, (SELECT CASE WHEN a.OperatorID = 981 THEN 'ETC出口' ELSE (SELECT OperatorName FROM dbtoms.tboperatorinfo WHERE a.OperatorID = OperatorID ORDER BY LastUpdateTime DESC LIMIT 1) END ) AS operatorName, IFNULL(SUM(CASE WHEN a.vehicleclass >0 then 1 else 0 end),0) AS totalCarNum, IFNULL(SUM(CASE WHEN a.vehicleclass>a.Rvehicleclass and a.Rvehicleclass <11 and a.vehicleclass>0 and a.DealStatus&14 != 14 then 1 else 0 end),0) AS sdCarNum FROM ${tableName} a
AND a.cancelflag=0 AND a.recordtype&1=1
AND a.StationID = #{stationId}
AND a.ExitDate >= #{intBeginTime}
AND a.ExitDate <= #{intEndTime}
GROUP BY OperatorID ORDER BY OperatorID

SELECT a.ExitDate AS resortTime, a.StationID AS stationId, (SELECT StationName FROM dbtoms.tbstationinfo WHERE a.StationID = StationID LIMIT 1 ) AS stationName, a.LaneID AS laneId, a.OperatorID AS operatorId, (SELECT OperatorName FROM dbtoms.tboperatorinfo WHERE a.OperatorID = OperatorID ORDER BY LastUpdateTime DESC LIMIT 1 ) AS operatorName, a.vehiclePlate AS vehicleLicense, a.inTime AS inTime FROM
SELECT * FROM ${tableName} AS alias${index + 1}
AND keyType IN (8, 24)
AND stationID in
#{stationId}
AND tradaDate >= #{intBeginTime}
AND tradaDate <= #{intEndTime}
a
